function draw() {
  shader(Shader);
	//Shader.setUniform("uniform",data);
  rect(0,0,width,height);
	//print(frameRate());
}
function getShader(_renderer) {
	const vert = `
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord = aTexCoord;
			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0; 
			gl_Position = positionVec4;
		}
	`;
	const frag = `
		precision highp float;
		varying vec2 vTexCoord;
		const float WIDTH=${windowWidth}.;
		const float HEIGHT=${windowHeight}.;
		vec2 random2(vec2 st){
    	st=vec2(dot(st,vec2(127.1,311.7)),dot(st,vec2(269.5,183.3)));
    	return -1.+2.*fract(sin(st)*43758.5453123);
		}
		float noise(vec2 st) {
			vec2 i = floor(st);
			vec2 f = fract(st);
			vec2 u = f*f*(3.-2.*f);
			return mix(mix(dot(random2(i+vec2(0.,0.)),f-vec2(0.,0.)),dot(random2(i+vec2(1.,0.)),f-vec2(1.,0.)),u.x),mix(dot(random2(i+vec2(0.,1.)),f-vec2(0.,1.)),dot(random2(i+vec2(1.,1.)),f-vec2(1.,1.)),u.x),u.y)/2.+.4;
		}
		void main() {
			float x = vTexCoord.x * WIDTH;
			float y = vTexCoord.y * HEIGHT;
			gl_FragColor = vec4(vec3(noise(vec2(x/50.,y/50.))),1.0);
		}
	`;
	return createShader(vert, frag);
}

